class _StandardsResolve(LocalCommand[StandardsResolve, StandardsResolved, StandardsResolved]):
    """``cad.standards.resolve`` v1. Proje standartlarını birleştir: Projeye bağlı
    standartları değiştirmeden birleşik bir standart hazırlar. Genel kurallar ilk
    kaynaktan, katman ve stil tanımları ile sürüm 2 çizgi tipi, tarama ve yayımlanmış
    blok referanslarının her adı ilk bulunduğu kaynaktan alınır. Tanımların kaynağı,
    kaynak sırası ve belge revizyonu sonuçla döner. Bu sorgu çizime hiçbir şey
    uygulamaz; sonucu cad.standards.check veya cad.standards.apply ile ayrı kullanın.
    Geçersiz veya eksik standart reddedilir.
    """
    __slots__ = ()
    id = "cad.standards.resolve"
    version = 1
    title = "Proje standartlarını birleştir"
    scope = "document"
    input_type = StandardsResolve
    output_type = StandardsResolved
    plan_type = StandardsResolved

    def __call__(
        self,
        doc: Document,
        /,
        *,
        request_id: str | None = None,
        expected: Expected | None = None,
    ) -> StandardsResolved:
        """Proje standartlarını birleştir: Projeye bağlı standartları değiştirmeden birleşik
        bir standart hazırlar. Genel kurallar ilk kaynaktan, katman ve stil tanımları ile
        sürüm 2 çizgi tipi, tarama ve yayımlanmış blok referanslarının her adı ilk bulunduğu
        kaynaktan alınır. Tanımların kaynağı, kaynak sırası ve belge revizyonu sonuçla
        döner. Bu sorgu çizime hiçbir şey uygulamaz; sonucu cad.standards.check veya
        cad.standards.apply ile ayrı kullanın. Geçersiz veya eksik standart reddedilir.

        Args:
            doc: The drawing it works on.
            request_id: Names this write: sent again with the same call it is answered as
                before and applied once (docs/adr/0253 §6).
            expected: What must still hold (:class:`Expected`: the revision, stamps, a plan's
                id); otherwise nothing is written and RevisionConflict is raised.

        Returns:
            StandardsResolved

        Raises:
            CommandFailed, NeedsInput, RevisionConflict: the command's refusal;
                nothing was written. Warnings go to :mod:`warnings` as CommandWarning.
        """
        return self.execute_input(doc, StandardsResolve(), request_id=request_id, expected=expected)

    def plan(
        self,
        doc: Document,
        /,
    ) -> StandardsResolved:
        """What it would write, with nothing written; the plan's ``revision``, given as
        ``expected_revision``, writes exactly this plan or nothing.
        """
        return self.plan_input(doc, StandardsResolve())

    def validate(
        self,
        doc: Document,
        /,
    ) -> list[CommandNote]:
        """Checks the input against the drawing, writing nothing; its warnings.
        A refusal raises as for the call.
        """
        return self.validate_input(doc, StandardsResolve())

    def answer(
        self,
        doc: Document,
        /,
        *,
        op: str = "execute",
        request_id: str | None = None,
        expected: Expected | None = None,
    ) -> Outcome[Any]:
        """``op`` (``execute``, ``plan`` or ``validate``) by the protocol (docs/adr/0253):
        the whole answer, a refusal in it rather than raised, with what it touched
        (``summary``), the plan's id (``plan_id``), whether the request was answered
        before (``replayed``) and its journal row (``call``).
        """
        return self.answer_input(doc, StandardsResolve(), op=op, request_id=request_id, expected=expected)


resolve = _StandardsResolve()
"""Proje standartlarını birleştir (``cad.standards.resolve``)."""


__all__ = ["apply", "check", "conflicts", "install", "resolve"]
